CREATE TABLE services(id UUID PRIMARY KEY,name VARCHAR(150) NOT NULL UNIQUE,base_price DECIMAL(12,2) NOT NULL CHECK(base_price>=0),active BOOLEAN NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE spare_parts(id UUID PRIMARY KEY,sku VARCHAR(80) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,unit_price DECIMAL(12,2) NOT NULL CHECK(unit_price>=0),stock_qty INTEGER NOT NULL CHECK(stock_qty>=0),active BOOLEAN NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE part_reservations(id UUID PRIMARY KEY,idempotency_key VARCHAR(100) NOT NULL UNIQUE,work_order_id UUID NOT NULL,response_payload TEXT NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE outbox_events(event_id UUID PRIMARY KEY,topic VARCHAR(120) NOT NULL,aggregate_id UUID NOT NULL,event_type VARCHAR(100) NOT NULL,payload TEXT NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,published BOOLEAN NOT NULL,published_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE processed_events(event_id UUID PRIMARY KEY,processed_at TIMESTAMP WITH TIME ZONE NOT NULL);
